export const BODY: string = "\n<p>گول کونے اور دائرہ کراپ دونوں تصویر کے کونوں کو نرم کرتے ہیں، مگر ان کا احساس بہت الگ ہے۔ گول کونے مربع تصویر کو نرم کرتے ہیں، دائرہ تصویر کو مکمل گول بنا دیتا ہے۔</p>\n<p>اوتار کے لیے دائرہ بہتر ہے، کارڈ کے لیے گول کونے بہتر ہیں۔ غلط شکل چننے سے تصویر عجیب لگتی ہے، چاہے وہ کتنی اچھی ہو۔</p>\n<p>یہ مضمون دونوں شکلوں کا موازنہ کرتا ہے، اور اوتار، کارڈ، سوشل، مصنوعات اور پرنٹ کے لیے درست انتخاب بتاتا ہے۔ شکل بدلنے کے لیے <a href=\"/ur/tasveer-ke-kone-gol-karein/\">راؤنڈ امیج کارنرز</a> استعمال کریں۔</p>\n<h2 id=\"what-each-shape-does\">ہر شکل کیا کرتی ہے</h2>\n<p>گول کونے تصویر کے چاروں کونوں کو قوس دیتے ہیں، مگر تصویر مربع ہی رہتی ہے۔ دائرہ کراپ تصویر کو مکمل گول بنا دیتا ہے، اور کونے مکمل ختم ہو جاتے ہیں۔</p>\n<p>گول کونے نرم اور جدید لگتے ہیں، جبکہ دائرہ دوستانہ اور ذاتی لگتا ہے۔ دونوں کا مقصد الگ ہے۔</p>\n<p>شکل چنتے وقت منزل دیکھیں: اوتار کے لیے دائرہ، کارڈ کے لیے گول کونے۔ منزل ہی شکل طے کرتی ہے۔</p>\n<h2 id=\"how-they-look\">دونوں ساتھ کیسی لگتی ہیں</h2>\n<p>ساتھ رکھنے پر فرق صاف نظر آتا ہے: گول کونے والی تصویر مربع لگتی ہے، دائرہ والی گول لگتی ہے۔ گول کونے تصویر کو کارڈ جیسا بناتے ہیں، دائرہ اسے سکے جیسا۔</p>\n<p>گول کونے والی تصویر میں زیادہ جگہ بچتی ہے، کیونکہ کونے صرف ہلکے گول ہوتے ہیں۔ دائرہ والی میں کونے مکمل کٹ جاتے ہیں، اس لیے تصویر چھوٹی لگتی ہے۔</p>\n<p>دونوں کو ساتھ دیکھ کر فیصلہ کریں: جو آپ کی منزل سے ملے، وہی چنیں۔</p>\n<h2 id=\"avatars\">اوتار: دائرہ اکثر جیتتا ہے</h2>\n<p>اوتار میں دائرہ بہتر ہے، کیونکہ زیادہ تر پلیٹ فارم اوتار کو دائرے میں دکھاتے ہیں۔ مربع تصویر اپ لوڈ کرنے پر بھی وہ دائرہ بن جاتی ہے۔</p>\n<p>دائرہ اوتار میں چہرہ درمیان میں ہونا چاہیے، تاکہ دائرے میں پورا چہرہ آئے۔ کندھوں تک کا کراپ دائرے میں بہتر لگتا ہے۔</p>\n<p>گول کونے والا اوتار بھی چل جاتا ہے، مگر پلیٹ فارم اسے دائرہ بنا دے گا۔ اس لیے پہلے سے دائرہ بنانا بہتر ہے۔</p>\n<h2 id=\"cards-and-ui\">کارڈ اور UI: گول کونے جیتتے ہیں</h2>\n<p>کارڈ میں گول کونے بہتر ہیں، کیونکہ کارڈ مربع ہوتا ہے اور گول کونے اسے نرم بناتے ہیں۔ دائرہ کارڈ میں نہیں چلتا، کیونکہ کارڈ میں متن اور تصویر دونوں ہوتے ہیں۔</p>\n<p>کارڈ کا رداس چھوٹا رکھیں، جیسے 12 پکسلز۔ بڑا رداس کارڈ کو دائرہ جیسا بنا دیتا ہے، جو عجیب لگتا ہے۔</p>\n<p>UI میں سب کارڈوں کا رداس ایک جیسا ہونا چاہیے، تاکہ ڈیزائن یکساں لگے۔</p>\n<h2 id=\"social-profiles\">سوشل پروفائل: پلیٹ فارم کو جانیں</h2>\n<p>ہر پلیٹ فارم کی اپنی شکل ہے: انسٹاگرام اوتار دائرے میں، فیس بک بھی دائرے میں، اور لنکڈ ان مربع میں دکھاتا ہے۔ پلیٹ فارم دیکھ کر شکل چنیں۔</p>\n<p>اگر آپ ایک ہی تصویر سب جگہ استعمال کرتے ہیں تو دائرہ چنیں، کیونکہ زیادہ تر پلیٹ فارم دائرہ استعمال کرتے ہیں۔</p>\n<p>پروفائل تصویر بنانے سے پہلے پلیٹ فارم کی گائیڈ دیکھیں۔ غلط شکل سے تصویر کا حصہ کٹ جاتا ہے۔</p>\n<h2 id=\"product-photos\">مصنوعات کی تصویریں: شکل اور بھروسہ</h2>\n<p>مصنوعات کی تصویر میں شکل بھروسے کو متاثر کرتی ہے۔ مربع یا ہلکے گول کونے پیشہ ورانہ لگتے ہیں، جبکہ دائرہ مصنوعات کو کھلونا بنا دیتا ہے۔</p>\n<p>مصنوعات کے لیے گول کونے چنیں، دائرہ نہیں۔ دائرہ مصنوعات کا حصہ کاٹ دیتا ہے، جس سے خریدار مصنوعات کو پورا نہیں دیکھ پاتا۔</p>\n<p>مصنوعات کی تصویر میں مستقل شکل رکھیں، تاکہ کیٹلاگ منظم لگے۔</p>\n<h2 id=\"screenshots\">اسکرین شاٹ: صرف گول کونے</h2>\n<p>اسکرین شاٹ میں صرف گول کونے چلتے ہیں، دائرہ نہیں۔ دائرہ اسکرین شاٹ کا متن کاٹ دیتا ہے، جس سے وہ ناقابل خواندگی ہو جاتا ہے۔</p>\n<p>اسکرین شاٹ کے کونے ہلکے گول کریں، تاکہ وہ کارڈ جیسا لگے۔ بڑا رداس متن کو کاٹ سکتا ہے۔</p>\n<p>اسکرین شاٹ کو PNG میں محفوظ کریں، تاکہ شفافیت بچے اور متن تیز رہے۔</p>\n<h2 id=\"transparency-needs\">شفافیت: دونوں شکلوں کو چاہیے</h2>\n<p>دونوں شکلوں کو شفافیت چاہیے، کیونکہ کٹا ہوا حصہ نظر نہیں آنا چاہیے۔ PNG یا WebP استعمال کریں، JPG نہیں۔</p>\n<p>JPG میں کٹا ہوا حصہ سفید ہو جاتا ہے، جو ہر پس منظر پر عجیب لگتا ہے۔ شفافیت کے بغیر شکل کا فائدہ ختم ہو جاتا ہے۔</p>\n<p>شفافیت جانچنے کے لیے تصویر کو رنگین پس منظر پر دیکھیں۔ اگر کونے نظر نہ آئیں تو شفافیت درست ہے۔</p>\n<h2 id=\"radius-vs-full-circle\">رداس بمقابلہ مکمل دائرہ: انتخاب نہیں، حد ہے</h2>\n<p>رداس اور دائرہ ایک ہی حد کے دو سرے ہیں: چھوٹا رداس ہلکا گول، بڑا رداس زیادہ گول، اور مکمل رداس دائرہ۔ یہ انتخاب نہیں، بلکہ رداس کی حد ہے۔</p>\n<p>رداس بڑھاتے جائیں تو تصویر آہستہ آہستہ دائرہ بن جاتی ہے۔ درمیان میں ہر رداس ایک الگ شکل دیتا ہے۔</p>\n<p>رداس چنتے وقت تصویر دیکھیں: جو رداس اچھا لگے، وہی چنیں۔ عدد سے زیادہ آنکھ اہم ہے۔</p>\n<h2 id=\"when-to-use-each\">ہر شکل کب استعمال کریں</h2>\n<p>اوتار کے لیے دائرہ، کارڈ کے لیے گول کونے، مصنوعات کے لیے ہلکے گول کونے، اور اسکرین شاٹ کے لیے ہلکے گول کونے چنیں۔</p>\n<p>شکل کا فیصلہ منزل سے کریں، پسند سے نہیں۔ منزل ہی بتاتی ہے کہ کون سی شکل درست ہے۔</p>\n<p>شک ہو تو گول کونے چنیں، کیونکہ وہ ہر جگہ چل جاتے ہیں۔ دائرہ صرف اوتار کے لیے ہے۔</p>\n<h2 id=\"combining-both\">دونوں شکلیں ملانا</h2>\n<p>دونوں شکلیں ایک ڈیزائن میں ملائی جا سکتی ہیں: دائرہ اوتار اور گول کونے کارڈ۔ یہ ملاپ عام ہے اور اچھا لگتا ہے۔</p>\n<p>ملاتے وقت رداس کو ہم آہنگ رکھیں: اوتار کا دائرہ اور کارڈ کا رداس ایک ہی خاندان سے لگنے چاہییں۔</p>\n<p>دونوں شکلیں ملانے سے ڈیزائن میں تنوع آتا ہے، مگر مستقل مزاجی بھی رہتی ہے۔</p>\n<h2 id=\"platform-rules\">پلیٹ فارم کے اصول: ہر سائٹ کیا چاہتی ہے</h2>\n<p>ہر پلیٹ فارم کے اپنے اصول ہیں: انسٹاگرام دائرہ، یوٹیوب دائرہ، اور ویب سائٹ گول کونے۔ اصول پڑھ کر شکل چنیں۔</p>\n<p>اصول بدلتے رہتے ہیں، اس لیے تازہ گائیڈ دیکھیں۔ پرانی یادداشت پر بھروسہ کرنا غلطی ہے۔</p>\n<p>اصول کی خلاف ورزی پر تصویر خود کٹ جاتی ہے، اور آپ کا کنٹرول ختم ہو جاتا ہے۔</p>\n<h2 id=\"common-mistakes\">شکلوں کے ساتھ عام غلطیاں</h2>\n<p>سب سے عام غلطی دائرہ مصنوعات کی تصویر پر لگانا ہے، جس سے مصنوعات کا حصہ کٹ جاتا ہے۔ دوسری غلطی JPG میں شکل بنانا ہے، جس سے کونے سفید ہو جاتے ہیں۔</p>\n<p>تیسری غلطی ہر تصویر پر الگ شکل ہے، جس سے ڈیزائن بے ترتیب لگتا ہے۔ ایک ہی منصوبے میں ایک ہی شکل رکھیں۔</p>\n<p>غلطیوں سے بچنے کے لیے شکل چننے سے پہلے منزل دیکھیں اور فارمیٹ جانچیں۔</p>\n<h2 id=\"print\">پرنٹ میں شکلیں</h2>\n<p>پرنٹ میں گول کونے اور دائرہ دونوں کاغذ پر کاٹے جاتے ہیں۔ ڈیجیٹل شکل پرنٹ میں ویسے نہیں نکلتی، اس لیے پرنٹر سے پوچھیں۔</p>\n<p>پرنٹ میں ٹھوس بھرنا چنیں، کیونکہ کاغذ شفاف نہیں ہوتا۔ شفاف کونے پرنٹ میں سفید نکلتے ہیں۔</p>\n<p>پرنٹ کے لیے شکل ڈیزائن میں بتائیں، فائل میں نہیں۔ پرنٹر کو بتائیں کہ کونے کیسے کاٹنے ہیں۔</p>\n<h2 id=\"choosing-cheat-sheet\">شکل چننے کی فوری یاد دہانی</h2>\n<p>اوتار کے لیے دائرہ، کارڈ کے لیے گول کونے، مصنوعات کے لیے ہلکے گول کونے، اور اسکرین شاٹ کے لیے ہلکے گول کونے۔ شک ہو تو گول کونے چنیں۔</p>\n<p>یاد دہانی کو فون میں محفوظ رکھیں، تاکہ ہر تصویر پر نیا فیصلہ نہ کرنا پڑے۔</p>\n<p>فوری فیصلہ کرنے کے لیے منزل پوچھیں: یہ تصویر کہاں دکھائی دے گی؟ جواب ہی شکل بتا دے گا۔</p>\n<h2 id=\"shapes-for-messaging\">پیغام رسانی ایپس کے لیے شکلیں</h2>\n<p>پیغام رسانی ایپس میں اوتار دائرے میں دکھایا جاتا ہے، اس لیے دائرہ چنیں۔ چیٹ میں بھیجی گئی تصویر گول کونوں میں اچھی لگتی ہے۔</p>\n<p>چیٹ میں تصویر چھوٹی دکھائی دیتی ہے، اس لیے شکل صاف ہونی چاہیے۔ چھوٹی تصویر پر بڑا رداس عجیب لگتا ہے۔</p>\n<p>پیغام رسانی میں بھیجی گئی تصویر کا میٹا ڈیٹا بھی جانچیں، تاکہ آپ کا مقام نہ جائے۔</p>\n<h2 id=\"shapes-for-email\">ای میل دستخط اور نیوز لیٹر کے لیے شکلیں</h2>\n<p>ای میل دستخط میں لوگو دائرے یا گول کونوں میں اچھا لگتا ہے۔ دستخط چھوٹا ہوتا ہے، اس لیے شکل صاف ہونی چاہیے۔</p>\n<p>نیوز لیٹر میں تصویر گول کونوں میں اچھی لگتی ہے، کیونکہ وہ کارڈ جیسی لگتی ہے۔ دائرہ نیوز لیٹر میں جگہ ضائع کرتا ہے۔</p>\n<p>ای میل میں تصویر PNG میں رکھیں، تاکہ شفافیت بچے۔ کونے گول کرنے کی مکمل رہنمائی <a href=\"/ur/blog/tasveer-kone-gol-karein-rehnumai/\">کونے گول کرنے کا رہنما</a> میں اور عملی مراحل <a href=\"/ur/blog/tasveer-ke-kone-kaise-gol-karein/\">تصویر کے کونے کیسے گول کریں</a> میں دیکھیں۔ بارڈر لگانا ہو تو <a href=\"/ur/tasveer-par-border-lagayein/\">امیج بارڈر جنریٹر</a> استعمال کریں۔</p>\n";

